<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { toDataURL } from 'qrcode'; import { deleteImageTransfer, deleteTransfer, type CreatedTransfer } from '../services/transfers'
const p=defineProps<{id:string}>(),r=useRouter(),raw=sessionStorage.getItem(`pastehub:transfer:${p.id}`),t=ref<CreatedTransfer|null>(raw?JSON.parse(raw) as CreatedTransfer:null),qr=ref(''),deleting=ref(false),left=ref('10:00')
function tick(){if(!t.value)return;const s=Math.ceil((new Date(t.value.expiresAt).getTime()-Date.now())/1000);left.value=s<=0?'Expired':`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`} async function remove(){if(!t.value)return;deleting.value=true;try{if(sessionStorage.getItem(`pastehub:transfer-kind:${p.id}`)==='image')await deleteImageTransfer(p.id,t.value.deleteToken);else await deleteTransfer(p.id,t.value.deleteToken);await r.replace('/expired')}finally{deleting.value=false}}
onMounted(async()=>{if(!t.value)return;tick();window.setInterval(tick,1000);qr.value=await toDataURL(t.value.pickupUrl,{margin:1,width:260,color:{dark:'#122035',light:'#ffffff'}})})
</script><template><section class="result-minimal"><h1>Sent.</h1><article v-if="t" class="sent-details"><img :src="qr" class="result-qr" alt="Pickup QR code"><strong class="result-code">{{ t.code }}</strong><p>Pick up with this code</p><div class="result-meta"><span>Expires in {{ left }}</span><button class="quiet-action" :disabled="deleting" @click="remove">{{ deleting?'Deleting…':'Delete' }}</button></div></article></section></template>
